layer.css:
@import url("https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,200..800&display=swap");
[data-ryt="pitch"] { color: var(--ryt-text); border-left: 6px solid color-mix(in srgb, var(--ryt-border) 27%, transparent); border-radius: 0px; font-family: "Bricolage Grotesque", serif; font-size: 16px; font-weight: 500; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 25px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { border-top: 1px solid color-mix(in srgb, var(--ryt-border) 27%, transparent); border-radius: 0px; transition: all; border-right: none; border-bottom: none; border-left: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 500; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: 4px; transition: color 0.08s }
[data-ryt="category"], [data-ryt="tags"] li { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 500; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: 4px; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: color 0.08s }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 32px; font-weight: 700; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 24px; font-weight: 700; font-style: normal; line-height: 2.083; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 4px; transition: color 0.08s }
[data-ryt="header"] { border-bottom: 1px solid color-mix(in srgb, var(--ryt-border) 27%, transparent); border-top: none }
[data-ryt="nav"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 500; font-style: normal; line-height: 2.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: 4px; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: color 0.08s }
[data-ryt="review"] { color: var(--ryt-text); font-family: "Bricolage Grotesque", serif; font-size: 13.3333px; font-weight: 500; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 12.8px; font-weight: 600; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 500; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: 4px; transition: color 0.08s }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 500; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: 4px; transition: color 0.08s }
[data-ryt="rec-card"] [data-ryt="title"]:hover { color: color-mix(in lab,#cd5c5c 60%,#fff 40%) }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: color-mix(in lab,#cd5c5c 60%,#fff 40%) }
[data-ryt="nav"] a:hover { color: color-mix(in lab,#cd5c5c 60%,#fff 40%) }
[data-ryt="brand"]:hover { color: color-mix(in lab,#cd5c5c 60%,#fff 40%) }
[data-ryt="category"]:hover, [data-ryt="tags"] li:hover { color: color-mix(in lab,#cd5c5c 60%,#fff 40%) }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: color-mix(in lab,#cd5c5c 60%,#fff 40%) }
